import importlib
import unittest

import main


def fresh():
    """每个用例都重载模块，避免模块级状态在用例之间串味。"""
    return importlib.reload(main)


class TestBehaviour(unittest.TestCase):
    def test_case_0(self):
        m = fresh()
        self.assertEqual(m.sum_inclusive(1, 5), 15)

    def test_case_1(self):
        m = fresh()
        self.assertEqual(m.sum_inclusive(3, 3), 3)

    def test_case_2(self):
        m = fresh()
        self.assertEqual(m.sum_inclusive(-2, 2), 0)


if __name__ == "__main__":
    unittest.main()

The bug is clear: `range(a, b)` excludes `b`, but the function should be inclusive.

